-- migration_024_new_questions_sept2026j.sql
-- Batch 10 of new questions from "questions to add.pdf" (Anatomy + Physiology):
--   q_mtf_meralgia_paraesthetica_lfcn_ultrasound_001 (MTF, Anatomy) -- new knowledge box
--     "Meralgia Paraesthetica" (LFCN anatomy, anatomical variant types A-E, aetiology/clinical
--     features, diagnosis/management + images/lfcn-anatomy.png, an English-relabelled version
--     of the source PDF's own reference illustration + embedded YouTube block video)
--     + relevantReading (BJA Education)
--   q_sba_lfcn_anatomy_001 (SBA, Anatomy) -- shares the same knowledge box + relevantReading
--   q_mtf_trpv1_receptor_001 (MTF, Physiology) -- new knowledge box "TRPV1 Receptor"
--     (structure/activators + new images/trpv1-activation-mechanism.svg, sensitisation,
--     distribution, clinical relevance) -- no relevantReading (PDF attached reading to the
--     separate Capsaicin box instead)
--   q_sba_capsaicin_patch_mechanism_001 (SBA, Physiology) -- new knowledge box "Capsaicin"
--     (mechanism, formulations, NNT/NNH efficacy tables, indications/cautions, practical
--     considerations) + relevantReading (BJA Education)
--
-- New image assets: images/lfcn-anatomy.png, images/trpv1-activation-mechanism.svg
-- No new categories (Anatomy, Physiology pre-exist).
--
-- Source-PDF note: the SBA anatomy question's option D ("usual path runs medial to the ASIS
-- within the sartorius origin") was marked False in the PDF with a rationale claiming
-- "Types B and D" run medial to the ASIS -- but per the PDF's own variant table, Type B runs
-- ANTERIOR to the ASIS, not medial. Rewrote the explanation to correctly state that D describes
-- something closer to the Type C course (medial to ASIS, ~23%), which is not the "usual" path
-- since Type B (anterior to ASIS, ~27%) is the single most common variant. The answer key
-- (False) is unchanged; only the supporting rationale was corrected.
--
-- Idempotent (on conflict do nothing); safe to re-run.

-- ===== New questions =====
insert into questions (id, type, data, status) values ('q_mtf_meralgia_paraesthetica_lfcn_ultrasound_001', 'MTF', '{"dateAdded":"2026-09-18","rotationIndex":122,"stem":"A 52-year-old man with confirmed meralgia paraesthetica continues to have numbness and dysaesthesia in the anterolateral thigh despite conservative measures. He is scheduled for an ultrasound-guided diagnostic injection of the lateral femoral cutaneous nerve. Expected sonographic findings include:","choices":["Increased intraneural vascularity","Sudden focal change in nerve diameter","Cross-sectional area measuring 2.70 mm²","Cross-sectional area measuring 1.50 mm²","Hyperechoic appearance of the nerve"],"correct":[true,true,true,false,false],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Ultrasound features of an entrapped or irritated lateral femoral cutaneous nerve (LFCN) include increased cross-sectional area, altered echogenicity, increased vascularity, and a focal change in calibre at the entrapment site &mdash; findings that support (but do not solely define) the diagnosis of meralgia paraesthetica.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; Pathological intraneural vascular flow, detected on power/colour Doppler, is frequently seen in an entrapped or irritated LFCN, reflecting a localised inflammatory/neuropathic response at the site of compression.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. TRUE</strong> &mdash; A segment of abrupt calibre alteration &mdash; often at the point where the nerve is compressed, classically near the inguinal ligament/ASIS &mdash; is a typical sonographic feature of nerve entrapment, reflecting focal swelling proximal to the compression point (pseudo-neuroma appearance).</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. TRUE</strong> &mdash; A cross-sectional area (CSA) above approximately 2.65mm&sup2; is consistent with meralgia paraesthetica, so a CSA of 2.70mm&sup2; falls above this threshold and supports the diagnosis.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. FALSE</strong> &mdash; A CSA of 1.50mm&sup2; is below the expected pathological threshold and would be more in keeping with a normal-calibre nerve rather than one affected by meralgia paraesthetica.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. FALSE</strong> &mdash; An affected LFCN tends to appear hypoechoic (darker) rather than hyperechoic on ultrasound, reflecting oedema and disruption of the normal fascicular echotexture &mdash; a hyperechoic appearance would be atypical for active nerve entrapment/inflammation.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Meralgia Paraesthetica</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The lateral femoral cutaneous nerve (LFCN) is a purely sensory branch of the lumbar plexus, vulnerable to entrapment beneath the inguinal ligament &mdash; the cause of meralgia paraesthetica.</p><div style=\"max-width:480px;margin:12px auto 0\"><div style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:10px;border:1px solid #EDE3D7\"><iframe src=\"https://www.youtube.com/embed/29mvc3uh-zw\" title=\"Lateral Femoral Cutaneous Nerve Block\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" allowfullscreen loading=\"lazy\"></iframe></div></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Anatomy of the LFCN</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Purely sensory nerve &mdash; no motor component</td></tr><tr><td>Arises from the dorsal divisions of the L2 and L3 nerve roots (lumbar plexus)</td></tr><tr><td>Emerges from the lateral border of psoas major and crosses the iliacus muscle obliquely</td></tr><tr><td>Passes under, over, or through the inguinal ligament, medial and inferior to the anterior superior iliac spine (ASIS) &mdash; the most common site of entrapment</td></tr><tr><td>Divides into anterior and posterior branches, supplying sensation to the anterolateral thigh (greater trochanter to knee)</td></tr><tr><td>Considerable anatomical variability exists in its course relative to the ASIS/inguinal ligament &mdash; why ultrasound guidance (rather than blind, landmark-based injection) improves accuracy for diagnostic/therapeutic blocks</td></tr></table><div style=\"text-align:center;margin-top:12px\"><img src=\"images/lfcn-anatomy.png\" alt=\"Illustration of the lateral femoral cutaneous nerve emerging near the psoas/iliacus, passing beneath the inguinal ligament, and its anterolateral thigh sensory territory, with English labels\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Anatomical Variants (Types A&ndash;E)</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The LFCN&rsquo;s course relative to the ASIS and inguinal ligament varies considerably between individuals, classified into five types:</p><table style=\"margin:12px 0 0\"><tr><th>Type</th><th>Frequency</th><th>Anatomical route</th></tr><tr><td><strong>A</strong></td><td>4%</td><td>Posterior to the ASIS, across the iliac crest</td></tr><tr><td><strong>B</strong></td><td>27%</td><td>Anterior to the ASIS and superficial to the origin of sartorius, within the substance of the inguinal ligament</td></tr><tr><td><strong>C</strong></td><td>23%</td><td>Medial to the ASIS, ensheathed in the tendinous origin of sartorius</td></tr><tr><td><strong>D</strong></td><td>26%</td><td>Medial to the origin of sartorius, between the sartorius tendon and the thick fascia of iliopsoas, deep to the inguinal ligament</td></tr><tr><td><strong>E</strong></td><td>20%</td><td>Most medial, embedded in loose connective tissue deep to the inguinal ligament, overlying the thin fascia of iliopsoas, contributing to the femoral branch of the genitofemoral nerve</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Types A&ndash;C run superficial to the inguinal ligament and are more vulnerable to direct mechanical trauma/surgical injury; Type B is the single most common variant, including among patients with meralgia paraesthetica.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Aetiology and Clinical Features</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Meralgia paraesthetica is a mononeuropathy caused by entrapment or compression of the LFCN, most commonly at or near the inguinal ligament/ASIS.</p><table style=\"margin:12px 0 0\"><tr><th>Risk factors</th><td>Obesity, pregnancy, tight clothing/belts, direct trauma, prolonged sitting/hip flexion, surgery near the anterior hip/pelvis (hip arthroplasty, ASIS bone graft harvesting, laparoscopic procedures), prolonged standing</td></tr><tr><th>Clinical features</th><td>Burning pain, numbness, tingling and dysaesthesia over the anterolateral thigh; purely sensory (no motor weakness, since the nerve carries no motor fibres); worsened by standing/walking/hip extension, relieved by sitting; pelvic compression test and Tinel&rsquo;s sign over the inguinal ligament may reproduce symptoms</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Diagnosis and Management</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Diagnosis is primarily clinical, supported by:</p><table style=\"margin:12px 0 0\"><tr><th>Investigation</th><th>Findings</th></tr><tr><td>Ultrasound</td><td>Increased cross-sectional area (&gt;~2.65mm&sup2;), hypoechoic nerve appearance, increased intraneural vascularity, focal calibre change at the entrapment site</td></tr><tr><td>Diagnostic nerve block</td><td>Local anaesthetic &plusmn; steroid &mdash; symptomatic relief supports the diagnosis</td></tr><tr><td>Nerve conduction studies</td><td>Less commonly used &mdash; technically difficult given the nerve&rsquo;s small size and variable course</td></tr></table><table style=\"margin:12px 0 0\"><tr><th>Management</th><th>Detail</th></tr><tr><td>Conservative (first-line)</td><td>Weight loss, avoiding tight clothing/belts, activity modification</td></tr><tr><td>Pharmacological</td><td>Neuropathic agents (gabapentinoids, TCAs)</td></tr><tr><td>Interventional</td><td>Ultrasound-guided LFCN block (local anaesthetic &plusmn; steroid) &mdash; diagnostic and often therapeutic; pulsed radiofrequency or neurolysis for refractory cases</td></tr><tr><td>Surgical</td><td>Nerve decompression or neurectomy &mdash; reserved for severe, refractory cases unresponsive to less invasive measures</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Meralgia Paraesthetica","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(25)00039-3/fulltext"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_lfcn_anatomy_001', 'SBA', '{"dateAdded":"2026-09-18","rotationIndex":123,"question":"With respect to the anatomy of the lateral femoral cutaneous nerve, which of the following statements is correct?","choices":["It divides into anterior, medial, and posterior branches","It provides motor innervation","It most commonly originates from the L1 nerve root","Its usual path runs medial to the ASIS within the sartorius origin","It supplies sensation to the anterolateral thigh"],"correct":4,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The LFCN is a purely sensory branch of the lumbar plexus with a highly variable course relative to the ASIS and inguinal ligament (see the knowledge box below); its only recognised sensory territory is the anterolateral thigh.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> The LFCN typically bifurcates into only anterior and posterior branches &mdash; there is no medial branch.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> It is exclusively a sensory nerve and carries no motor fibres.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> It generally arises from the dorsal (posterior) divisions of the L2 and L3 nerve roots, not L1.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> This describes a course resembling the Type C variant (medial to the ASIS, ensheathed in the tendinous origin of sartorius, ~23% of cases) &mdash; but this is not the &ldquo;usual&rdquo; path. Type B (anterior to the ASIS, superficial to the origin of sartorius, ~27%) is the single most common variant, so no course medial to the ASIS can be called usual.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Correct.</strong> Its recognised sensory territory is the anterolateral thigh, from the greater trochanter to the knee.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Meralgia Paraesthetica</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The lateral femoral cutaneous nerve (LFCN) is a purely sensory branch of the lumbar plexus, vulnerable to entrapment beneath the inguinal ligament &mdash; the cause of meralgia paraesthetica.</p><div style=\"max-width:480px;margin:12px auto 0\"><div style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:10px;border:1px solid #EDE3D7\"><iframe src=\"https://www.youtube.com/embed/29mvc3uh-zw\" title=\"Lateral Femoral Cutaneous Nerve Block\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" allowfullscreen loading=\"lazy\"></iframe></div></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Anatomy of the LFCN</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Purely sensory nerve &mdash; no motor component</td></tr><tr><td>Arises from the dorsal divisions of the L2 and L3 nerve roots (lumbar plexus)</td></tr><tr><td>Emerges from the lateral border of psoas major and crosses the iliacus muscle obliquely</td></tr><tr><td>Passes under, over, or through the inguinal ligament, medial and inferior to the anterior superior iliac spine (ASIS) &mdash; the most common site of entrapment</td></tr><tr><td>Divides into anterior and posterior branches, supplying sensation to the anterolateral thigh (greater trochanter to knee)</td></tr><tr><td>Considerable anatomical variability exists in its course relative to the ASIS/inguinal ligament &mdash; why ultrasound guidance (rather than blind, landmark-based injection) improves accuracy for diagnostic/therapeutic blocks</td></tr></table><div style=\"text-align:center;margin-top:12px\"><img src=\"images/lfcn-anatomy.png\" alt=\"Illustration of the lateral femoral cutaneous nerve emerging near the psoas/iliacus, passing beneath the inguinal ligament, and its anterolateral thigh sensory territory, with English labels\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Anatomical Variants (Types A&ndash;E)</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The LFCN&rsquo;s course relative to the ASIS and inguinal ligament varies considerably between individuals, classified into five types:</p><table style=\"margin:12px 0 0\"><tr><th>Type</th><th>Frequency</th><th>Anatomical route</th></tr><tr><td><strong>A</strong></td><td>4%</td><td>Posterior to the ASIS, across the iliac crest</td></tr><tr><td><strong>B</strong></td><td>27%</td><td>Anterior to the ASIS and superficial to the origin of sartorius, within the substance of the inguinal ligament</td></tr><tr><td><strong>C</strong></td><td>23%</td><td>Medial to the ASIS, ensheathed in the tendinous origin of sartorius</td></tr><tr><td><strong>D</strong></td><td>26%</td><td>Medial to the origin of sartorius, between the sartorius tendon and the thick fascia of iliopsoas, deep to the inguinal ligament</td></tr><tr><td><strong>E</strong></td><td>20%</td><td>Most medial, embedded in loose connective tissue deep to the inguinal ligament, overlying the thin fascia of iliopsoas, contributing to the femoral branch of the genitofemoral nerve</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Types A&ndash;C run superficial to the inguinal ligament and are more vulnerable to direct mechanical trauma/surgical injury; Type B is the single most common variant, including among patients with meralgia paraesthetica.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Aetiology and Clinical Features</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Meralgia paraesthetica is a mononeuropathy caused by entrapment or compression of the LFCN, most commonly at or near the inguinal ligament/ASIS.</p><table style=\"margin:12px 0 0\"><tr><th>Risk factors</th><td>Obesity, pregnancy, tight clothing/belts, direct trauma, prolonged sitting/hip flexion, surgery near the anterior hip/pelvis (hip arthroplasty, ASIS bone graft harvesting, laparoscopic procedures), prolonged standing</td></tr><tr><th>Clinical features</th><td>Burning pain, numbness, tingling and dysaesthesia over the anterolateral thigh; purely sensory (no motor weakness, since the nerve carries no motor fibres); worsened by standing/walking/hip extension, relieved by sitting; pelvic compression test and Tinel&rsquo;s sign over the inguinal ligament may reproduce symptoms</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Diagnosis and Management</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Diagnosis is primarily clinical, supported by:</p><table style=\"margin:12px 0 0\"><tr><th>Investigation</th><th>Findings</th></tr><tr><td>Ultrasound</td><td>Increased cross-sectional area (&gt;~2.65mm&sup2;), hypoechoic nerve appearance, increased intraneural vascularity, focal calibre change at the entrapment site</td></tr><tr><td>Diagnostic nerve block</td><td>Local anaesthetic &plusmn; steroid &mdash; symptomatic relief supports the diagnosis</td></tr><tr><td>Nerve conduction studies</td><td>Less commonly used &mdash; technically difficult given the nerve&rsquo;s small size and variable course</td></tr></table><table style=\"margin:12px 0 0\"><tr><th>Management</th><th>Detail</th></tr><tr><td>Conservative (first-line)</td><td>Weight loss, avoiding tight clothing/belts, activity modification</td></tr><tr><td>Pharmacological</td><td>Neuropathic agents (gabapentinoids, TCAs)</td></tr><tr><td>Interventional</td><td>Ultrasound-guided LFCN block (local anaesthetic &plusmn; steroid) &mdash; diagnostic and often therapeutic; pulsed radiofrequency or neurolysis for refractory cases</td></tr><tr><td>Surgical</td><td>Nerve decompression or neurectomy &mdash; reserved for severe, refractory cases unresponsive to less invasive measures</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Meralgia Paraesthetica","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(25)00039-3/fulltext"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_trpv1_receptor_001', 'MTF', '{"dateAdded":"2026-09-18","rotationIndex":124,"stem":"Regarding the TRPV1 receptor:","choices":["TRPV1 is activated by noxious heat above approximately 43°C","TRPV1 is a ligand-gated chloride channel","Anandamide is an endogenous agonist at TRPV1","TRPV1 is sensitised by bradykinin","TRPV1 is exclusively expressed on peripheral nociceptor terminals, with no central nervous system distribution"],"correct":[true,false,true,true,false],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">TRPV1 (transient receptor potential vanilloid 1) is a thermosensitive, ligand-gated non-selective cation channel central to nociceptor activation and sensitisation.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; TRPV1 is activated by noxious heat, with an activation threshold of approximately 43&deg;C and above &mdash; corresponding to the temperature at which humans begin to perceive heat as painful.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. FALSE</strong> &mdash; TRPV1 is a non-selective cation channel, permeable primarily to calcium (and to a lesser extent sodium), not a chloride channel &mdash; activation causes depolarisation via cation influx, contributing to nociceptor activation.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. TRUE</strong> &mdash; Anandamide, an endogenous cannabinoid, is also an endogenous agonist at TRPV1, illustrating the overlap between the endocannabinoid and TRPV1 signalling systems.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. TRUE</strong> &mdash; TRPV1 is sensitised (its activation threshold lowered) by inflammatory mediators including bradykinin, nerve growth factor (NGF), and prostaglandins, largely via protein kinase C (PKC)-mediated phosphorylation of the channel, contributing to peripheral sensitisation and inflammatory hyperalgesia.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. FALSE</strong> &mdash; While TRPV1 is most classically described on peripheral nociceptor terminals (small-diameter A&delta; and C fibres), it is also expressed at central sites, including the spinal cord dorsal horn and certain brain areas, contributing to central as well as peripheral nociceptive signalling.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">TRPV1 Receptor</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">TRPV1 (transient receptor potential vanilloid 1) is a thermosensitive, ligand-gated cation channel central to nociceptor activation and sensitisation.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Structure, Classification and Activators</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">TRPV1 is a member of the Transient Receptor Potential (TRP) ion channel superfamily, vanilloid subfamily &mdash; a ligand-gated, non-selective cation channel highly permeable to calcium.</p><table style=\"margin:12px 0 0\"><tr><th>Activator</th><th>Detail</th></tr><tr><td>Capsaicin</td><td>The pungent component of chilli peppers &mdash; the prototypical exogenous agonist</td></tr><tr><td>Noxious heat</td><td>&gt;~43&deg;C &mdash; the temperature at which humans begin to perceive heat as painful</td></tr><tr><td>Low pH / protons</td><td>Acidic environment, e.g. inflamed or ischaemic tissue</td></tr><tr><td>Endogenous lipid ligands</td><td>Anandamide, certain lipoxygenase products (e.g. 12-HPETE)</td></tr><tr><td>Resiniferatoxin</td><td>An ultrapotent capsaicin analogue used experimentally/therapeutically</td></tr></table><div style=\"text-align:center;margin-top:12px\"><img src=\"images/trpv1-activation-mechanism.svg\" alt=\"TRPV1 channel activation by heat, capsaicin, protons and anandamide causing calcium influx, nociceptor depolarisation and substance P/CGRP release, with sensitisation by inflammatory mediators via PKC/PKA\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Sensitisation Mechanisms</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Inflammatory mediators &mdash; bradykinin, nerve growth factor (NGF), prostaglandins, ATP &mdash; sensitise TRPV1 (lower its activation threshold) via intracellular signalling, principally protein kinase C (PKC) and protein kinase A (PKA)-mediated phosphorylation.</p><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">This sensitisation contributes to inflammatory hyperalgesia and thermal allodynia (pain from previously non-painful warmth).</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Distribution</div><table style=\"margin:0\"><tr><th>Site</th><th>Detail</th></tr><tr><td>Peripheral</td><td>Predominantly expressed on peripheral nociceptor terminals (small-diameter A&delta; and C fibres)</td></tr><tr><td>Central</td><td>Also present in the spinal cord dorsal horn and select brain regions</td></tr><tr><td>Non-neuronal</td><td>Also described in keratinocytes and urothelium, contributing to roles beyond classical nociception</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical Relevance</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Topical capsaicin (low-dose creams, and the high-concentration 8% patch, Qutenza) produces analgesia via sustained TRPV1 activation leading to reversible nociceptor defunctionalisation, used in post-herpetic neuralgia and other peripheral neuropathic pain conditions &mdash; see the separate Capsaicin knowledge box for full detail.</p></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_capsaicin_patch_mechanism_001', 'SBA', '{"dateAdded":"2026-09-18","rotationIndex":125,"question":"Which of the following best describes the mechanism by which topical capsaicin 8% patches produce prolonged analgesia?","choices":["Competitive antagonism at TRPV1 receptors","Sustained TRPV1 activation","Direct blockade of voltage-gated sodium channels","Inhibition of cyclooxygenase within peripheral nociceptor terminals","Upregulation of GABA-A receptor expression in the dorsal horn"],"correct":1,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Capsaicin is a potent TRPV1 agonist, not an antagonist. High-concentration topical application produces intense initial activation of TRPV1-expressing nociceptor terminals, causing a large, sustained calcium influx. This calcium overload leads to a reversible &ldquo;defunctionalisation&rdquo; of the treated terminals &mdash; mitochondrial dysfunction, retraction of epidermal nerve fibres, and loss of the terminal&rsquo;s capacity to transduce and transmit pain signals &mdash; producing analgesia lasting weeks to months as the nerve terminals gradually regenerate.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> Capsaicin is an agonist, not an antagonist, at TRPV1; its analgesic effect arises from over-activation and subsequent desensitisation/defunctionalisation.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Correct.</strong> Accurately describes the accepted mechanism of high-concentration topical capsaicin analgesia.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Sodium channel blockade is not the primary mechanism of capsaicin; this describes the mechanism of local anaesthetics instead.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> COX inhibition describes the mechanism of NSAIDs, not capsaicin/TRPV1 activation.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> GABA-A receptor upregulation is not a recognised mechanism of capsaicin action; this is unrelated to TRPV1 pharmacology.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Capsaicin</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Capsaicin, the pungent active component of chilli peppers, produces analgesia through sustained TRPV1 activation rather than receptor blockade.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Pharmacology / Mechanism of Action</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Capsaicin is a vanilloid compound and a potent agonist at TRPV1, normally activated by noxious heat (&gt;~43&deg;C). Initial activation causes an intense calcium influx, triggering acute nociceptor firing (the characteristic burning sensation) and substance P/CGRP release from the terminal (neurogenic inflammation &mdash; local flare/vasodilation).</p><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">With continued/repeated exposure, substance P depletion (release exceeding synthesis) reduces the terminal&rsquo;s capacity for further neurotransmission. With high-concentration exposure, sustained calcium overload causes mitochondrial dysfunction and reversible defunctionalisation of the nociceptor terminal (epidermal nerve fibre retraction), producing more prolonged analgesia until reinnervation occurs over subsequent weeks to months.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Formulations</div><table style=\"margin:0\"><tr><th>Formulation</th><th>Detail</th></tr><tr><td><strong>Low-dose cream (0.075%)</strong></td><td>Applied regularly (typically 3&ndash;4 times daily) by the patient at home; mechanism mainly substance P depletion with repeated use</td></tr><tr><td><strong>High-concentration patch (8%) &mdash; Qutenza</strong></td><td>Single 30&ndash;60 minute application under supervision (with local anaesthetic pretreatment given the intense initial burning), repeated every ~90 days if needed; mechanism mainly TRPV1-mediated nociceptor defunctionalisation</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Efficacy (NNT) and Harm (NNH)</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Data from a Cochrane review (Derry et al. 2009):</p><table style=\"margin:12px 0 0\"><tr><th>Formulation</th><th>Outcome measured</th><th>NNT (95% CI)</th></tr><tr><td>Low-dose cream (0.075%), regular application</td><td>Any pain relief at 6&ndash;8 weeks</td><td>6.6 (4.1&ndash;17)</td></tr><tr><td>High-dose patch (8%), single application</td><td>&ge;30% pain relief at 12 weeks</td><td>12 (6.4&ndash;70)</td></tr></table><table style=\"margin:12px 0 0\"><tr><th>Formulation</th><th>Outcome measured</th><th>NNH (95% CI)</th></tr><tr><td>Low-dose cream (0.075%), repeated application</td><td>Local skin reaction leading to withdrawal</td><td>2.5 (2.1&ndash;3.1)</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Local skin irritation/burning is common with capsaicin (of either formulation) but is generally mild, transient, and attenuates with continued/repeated use. Systemic adverse effects are rare.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Indications and Cautions</div><table style=\"margin:0\"><tr><th>Indications</th><td>Post-herpetic neuralgia, painful diabetic peripheral neuropathy, HIV-associated sensory neuropathy, other localised peripheral neuropathic pain syndromes. Low-dose cream also used more broadly for musculoskeletal pain (e.g. osteoarthritis) in some formulations</td></tr><tr><th>Contraindications / cautions</th><td>Hypersensitivity to capsaicin or any patch/cream component; application to broken, inflamed, irritated, or damaged skin; avoid contact with eyes, mucous membranes, and non-intact skin; high-concentration patch &mdash; caution in uncontrolled hypertension (transient BP rise can occur during/after application) with BP monitoring recommended, not for use on the face/scalp/near mucous membranes; caution in patients with poor peripheral sensation who may not reliably detect excessive skin irritation/burns</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Practical Considerations</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>High-concentration patch application requires pretreatment with topical local anaesthetic to the treatment area, given the intense initial burning sensation on application</td></tr><tr><td>Patients should be warned that a transient worsening of pain is common immediately after application (both formulations), before any benefit is felt</td></tr><tr><td>Hands should be washed thoroughly after application (or gloves worn) to avoid inadvertent transfer to eyes/mucous membranes/other skin areas</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Post-herpetic Neuralgia","source":"BJA Education","url":"https://www.bjaed.org/article/S1743-1816(17)30143-9/fulltext"}]}'::jsonb, 'published')
  on conflict (id) do nothing;

